namespace Scheduling;

/// <summary>
/// Provides the scheduling API by coordinating focused scheduling services.
/// </summary>
public sealed class ScheduleManager
{
    private readonly PlacementService _placements = new();
    private readonly ResourceMatchingService _matching = new();
    private readonly ConflictService _conflicts = new();
    private readonly NotificationService _notifications = new();

    public string Place(Job job, Resource resource) => _placements.Place(job, resource);

    public bool Unplace(Job job) => _placements.Unplace(job);

    public int PlacementCount => _placements.Count;

    public Resource? Match(Job job, IReadOnlyList<Resource> resources) =>
        _matching.Match(job, resources);

    public void RecordDemand(Job job) => _matching.RecordDemand(job);

    public int DemandFor(string skill) => _matching.DemandFor(skill);

    public bool HasConflict(Slot candidate) => _conflicts.HasConflict(candidate);

    public bool Book(Slot candidate) => _conflicts.Book(candidate);

    public int Overlaps(Slot candidate) => _conflicts.Overlaps(candidate);

    public bool Notify(Job job) =>
        _notifications.Notify(job, _placements.IsPlaced(job.Id));

    public string Reschedule(Job job, Resource resource) =>
        _placements.Reschedule(job, resource);

    public int ResolveConflicts(Slot candidate) => _conflicts.ResolveConflicts(candidate);

    public string Escalate(Job job) => _notifications.Escalate(job);

    public int NotifiedCount => _notifications.Count;
}

internal sealed class PlacementService
{
    private const int MaximumCalendarEntries = 50;
    private readonly Dictionary<string, string> _placements = new(StringComparer.Ordinal);

    public int Count => _placements.Count;

    public string Place(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (_placements.ContainsKey(job.Id))
            return "already placed";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Calendar.Count > MaximumCalendarEntries)
            return "resource full";

        _placements[job.Id] = resource.Name;
        return resource.Name;
    }

    public bool Unplace(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return false;

        return _placements.Remove(job.Id);
    }

    public bool IsPlaced(string id) =>
        !string.IsNullOrEmpty(id) && _placements.ContainsKey(id);

    public string Reschedule(Job job, Resource resource)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_placements.ContainsKey(job.Id))
            return "not placed";
        if (resource.Calendar.Count > MaximumCalendarEntries)
            return "target full";
        if (job.Duration <= TimeSpan.Zero)
            return "bad duration";
        if (resource.Skills.Count == 0)
            return "no skills";
        if (!string.IsNullOrEmpty(job.RequiredSkill) &&
            !resource.Skills.Contains(job.RequiredSkill))
            return "skill mismatch";

        _placements[job.Id] = resource.Name;
        return job.Priority > 7 ? $"{resource.Name}:priority" : resource.Name;
    }
}

internal sealed class ResourceMatchingService
{
    private readonly Dictionary<string, int> _skillDemand =
        new(StringComparer.OrdinalIgnoreCase);

    public Resource? Match(Job job, IReadOnlyList<Resource> resources)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return null;

        Resource? best = null;
        foreach (var resource in resources)
        {
            if (!resource.Skills.Contains(job.RequiredSkill))
                continue;
            if (best == null || resource.Calendar.Count < best.Calendar.Count)
                best = resource;
        }

        return best;
    }

    public void RecordDemand(Job job)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            return;

        var current = _skillDemand.TryGetValue(job.RequiredSkill, out var count) ? count : 0;
        _skillDemand[job.RequiredSkill] = current + (job.Priority > 5 ? 2 : 1);
    }

    public int DemandFor(string skill)
    {
        if (string.IsNullOrEmpty(skill))
            return 0;

        return _skillDemand.TryGetValue(skill, out var count) ? count : 0;
    }
}

internal sealed class ConflictService
{
    private readonly List<Slot> _booked = new();

    public bool HasConflict(Slot candidate)
    {
        if (!IsValid(candidate))
            return true;

        foreach (var booked in _booked)
        {
            if (Overlaps(candidate, booked))
                return true;
        }

        return false;
    }

    public bool Book(Slot candidate)
    {
        if (!IsValid(candidate) || HasConflict(candidate))
            return false;
        if (candidate.Start.Hour < 6 || candidate.End.Hour > 22)
            return false;

        _booked.Add(candidate);
        return true;
    }

    public int Overlaps(Slot candidate)
    {
        var count = 0;
        foreach (var booked in _booked)
        {
            if (Overlaps(candidate, booked))
                count++;
        }

        return count;
    }

    public int ResolveConflicts(Slot candidate)
    {
        if (!IsValid(candidate))
            return -1;

        var resolved = 0;
        var keep = new List<Slot>();
        foreach (var booked in _booked)
        {
            if (!Overlaps(candidate, booked))
            {
                keep.Add(booked);
                continue;
            }

            if (booked.End - booked.Start < candidate.End - candidate.Start)
                resolved++;
            else if (booked.Start < candidate.Start)
                keep.Add(booked);
            else
                resolved++;
        }

        if (resolved > 0)
            _booked.Clear();
        foreach (var slot in keep)
            _booked.Add(slot);

        return resolved;
    }

    private static bool IsValid(Slot slot) => slot.End > slot.Start;

    private static bool Overlaps(Slot first, Slot second) =>
        first.Start < second.End && second.Start < first.End;
}

internal sealed class NotificationService
{
    private readonly HashSet<string> _notified = new(StringComparer.Ordinal);

    public int Count => _notified.Count;

    public bool Notify(Job job, bool isPlaced)
    {
        if (string.IsNullOrEmpty(job.Id) ||
            _notified.Contains(job.Id) ||
            !isPlaced ||
            job.Priority <= 0)
            return false;

        _notified.Add(job.Id);
        return true;
    }

    public string Escalate(Job job)
    {
        if (string.IsNullOrEmpty(job.Id))
            return "no id";
        if (!_notified.Contains(job.Id))
            return "not notified";
        if (job.Priority > 9)
            return "exec";
        if (job.Priority > 7)
            return "manager";
        if (job.Priority > 4)
            return "lead";
        if (job.Duration.TotalHours > 24)
            return "long-running";
        if (_notified.Count > 100 && job.Priority > 0)
            return "batch";

        return "none";
    }
}
